package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.RecoverPassEmailTemplateVO;

class RecoverPassEmailTemplateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of recover pass email template of tenant config")
  void test_recover_pass_email_template_value_holder_assign_plain_value() {
    Object holder = new Object();
    RecoverPassEmailTemplateValueHolder<Object> value =
        new RecoverPassEmailTemplateValueHolder<>(holder);
    Assertions.assertSame(holder, value.recoverPassEmailTemplate("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRecoverPassEmailTemplateValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getRecoverPassEmailTemplate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.recoverPassEmailTemplateNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRecoverPassEmailTemplateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getRecoverPassEmailTemplate().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of recover pass email template of tenant config")
  void test_recover_pass_email_template_value_holder_assign_value_object() {
    Object holder = new Object();
    RecoverPassEmailTemplateValueHolder<Object> value =
        new RecoverPassEmailTemplateValueHolder<>(holder);
    RecoverPassEmailTemplateVO vo = RecoverPassEmailTemplateVO.from("one");
    Assertions.assertFalse(value.getRecoverPassEmailTemplateValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.recoverPassEmailTemplate(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getRecoverPassEmailTemplateValue().orElseThrow());
    Assertions.assertSame(holder, value.recoverPassEmailTemplate(Optional.empty()));
    Assertions.assertFalse(value.getRecoverPassEmailTemplateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.recoverPassEmailTemplate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRecoverPassEmailTemplateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of recover pass email template of tenant config against the original")
  void test_recover_pass_email_template_value_holder_read() {
    Object holder = new Object();
    RecoverPassEmailTemplateValueHolder<Object> value =
        new RecoverPassEmailTemplateValueHolder<>(holder);
    RecoverPassEmailTemplateVO vo = RecoverPassEmailTemplateVO.from("one");
    RecoverPassEmailTemplateVO other = RecoverPassEmailTemplateVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getRecoverPassEmailTemplateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRecoverPassEmailTemplate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readRecoverPassEmailTemplate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.recoverPassEmailTemplate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRecoverPassEmailTemplate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRecoverPassEmailTemplate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of recover pass email template of tenant config")
  void test_recover_pass_email_template_value_holder_unset() {
    Object holder = new Object();
    RecoverPassEmailTemplateValueHolder<Object> value =
        new RecoverPassEmailTemplateValueHolder<>(holder);
    RecoverPassEmailTemplateVO vo = RecoverPassEmailTemplateVO.from("one");
    value.recoverPassEmailTemplate(vo);
    Assertions.assertSame(holder,
        value.unsetRecoverPassEmailTemplateIfMatches("recoverPassEmailTemplate_other"));
    Assertions.assertTrue(value.getRecoverPassEmailTemplateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetRecoverPassEmailTemplateIfMatches("recoverPassEmailTemplate"));
    Assertions.assertFalse(value.getRecoverPassEmailTemplateValue().isPresent(),
        "The field name must clear the value");
    value.recoverPassEmailTemplate(vo);
    Assertions.assertSame(holder, value.unsetRecoverPassEmailTemplate());
    Assertions.assertFalse(value.getRecoverPassEmailTemplateValue().isPresent(),
        "Unset must clear the value");
  }
}
